-- Spec 020: upload activity. Every asset created by one POST /assets or POST /assets/bulk shares an
-- upload_batch_id, so an upload operation (and a bulk upload's 'mixed' file type) can be found.
-- The schema is not generated by Hibernate (ddl-auto=none), so apply this to MariaDB by hand.

-- The column must have the same type as assets.id (Hibernate binds both UUIDs the same way), so copy it.
SET @id_type = (SELECT COLUMN_TYPE FROM information_schema.COLUMNS
                WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'assets' AND COLUMN_NAME = 'id');
SET @ddl = CONCAT('ALTER TABLE assets ADD COLUMN upload_batch_id ', @id_type, ' NULL');
PREPARE add_column FROM @ddl;
EXECUTE add_column;
DEALLOCATE PREPARE add_column;

-- The activity queries select assets created after a point in time.
CREATE INDEX idx_assets_created_at ON assets (created_at);

-- Existing assets keep a NULL batch id and each counts as its own upload operation.
